INSERT INTO woorido.expense_votes (
  id, challenge_id, created_by, title, description,
  status, required_count,
  created_at, expires_at
) VALUES (
  #{id}, #{challengeId}, #{createdBy}, #{title}, #{description},
  #{status}, #{requiredCount},
  #{createdAt}, #{expiresAt}
)

INSERT INTO woorido.expense_vote_records (
  id, expense_vote_id, user_id, choice, created_at
) VALUES (
  #{id}, #{expenseVoteId}, #{userId}, #{choice}, CURRENT_TIMESTAMP
)
